// R3: fan a draft's messages[] into one item per message
const draft = $('Parse Callback').first().json.draft;
const msgs = (draft && Array.isArray(draft.messages) && draft.messages.length)
  ? draft.messages
  : [ (draft && draft.draft_text) || '(empty draft)' ];
return msgs.map((m, i) => ({
  json: { chatId: draft.customer_phone, text: String(m), seq: i + 1, total: msgs.length, draft_id: draft.id }
}));

// #1: build conversation_history from the WhatsApp thread (via WAHA)
const wh = $('WAHA Webhook').first().json.body.payload;
const currentId = wh.id;
const chatId = wh.from;

let msgs = [];
for (const it of $input.all()) {
  const j = it.json;
  if (j && typeof j.body === 'string' && typeof j.fromMe === 'boolean' && j.timestamp) {
    msgs.push(j);
  } else if (Array.isArray(j)) {
    for (const m of j) { if (m && typeof m.body === 'string') msgs.push(m); }
  }
}
msgs = msgs
  .filter(m => m.body && String(m.body).trim() && m.id !== currentId)
  .sort((a, b) => (a.timestamp || 0) - (b.timestamp || 0));

const now = Math.floor(Date.now() / 1000);
function ago(ts) {
  const s = Math.max(0, now - (ts || now));
  if (s < 90) return 'just now';
  if (s < 5400) return Math.round(s / 60) + 'm ago';
  if (s < 129600) return Math.round(s / 3600) + 'h ago';
  return Math.round(s / 86400) + 'd ago';
}

let history;
if (msgs.length === 0) {
  history = 'First contact, no prior messages.';
} else {
  history = msgs.slice(-15).map(function (m) {
    const who = m.fromMe ? 'Dubriani' : 'Customer';
    const body = String(m.body).replace(/\s+/g, ' ').trim();
    return who + ' (' + ago(m.timestamp) + '): "' + body + '"';
  }).join('\n');
}

return [{ json: {
  conversationHistory: history,
  historyCount: msgs.length,
  customerChatId: chatId,
  customerName: wh.notifyName || wh.pushName || '',
  userMessage: wh.body || ''
} }];
